#!/usr/bin/env python3
"""Build a self-contained Folio report from measured load results and browser screenshots."""
import base64
import html
import json
import os
from datetime import datetime
from zoneinfo import ZoneInfo
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
LATEST = json.loads((ROOT / '.local/stress/latest.json').read_text())
RESULT = json.loads((ROOT / os.environ.get('STRESS_REPORT_INPUT', LATEST['path'])).read_text())
BASELINE = json.loads((ROOT / 'docs/stress-baseline-2026-10-25.json').read_text())
BEFORE = {'phases':[BASELINE['admissionBefore']]}
OUTPUT = ROOT / 'output/stress-report'
OUTPUT.mkdir(parents=True, exist_ok=True)
PHASES = RESULT['phases']
SUMMARY = RESULT['summary']

def percentile(values, p):
    values = sorted(values)
    return values[max(0, int(len(values) * p + .999999) - 1)] if values else 0

requests = RESULT['requests']
measured = [r for r in requests if r['phase'] not in ('setup', 'cleanup')]
route_groups = {}
for r in measured:
    key = (r['method'], r['route'])
    route_groups.setdefault(key, []).append(r)
routes = []
for (method, route), samples in route_groups.items():
    routes.append({'method': method, 'route': route, 'count': len(samples), 'p50': round(percentile([r['ms'] for r in samples], .5)), 'p95': round(percentile([r['ms'] for r in samples], .95)), 'p99': round(percentile([r['ms'] for r in samples], .99)), 'errors': sum(not r['expected'] for r in samples)})
routes.sort(key=lambda r: -r['count'])

counts = {}
for phase in PHASES:
    for state, count in phase.get('expectedStates', {}).items():
        counts[state] = counts.get(state, 0) + count
phase_stats = []
for phase in PHASES:
    samples = [r for r in measured if r['phase'] == phase['name']]
    phase_stats.append({**phase, 'httpP95': round(percentile([r['ms'] for r in samples], .95)), 'saveP95': round(percentile([r['ms'] for r in samples if r['method'] == 'PUT'], .95)), 'overviewP95': round(percentile([r['ms'] for r in samples if r['route'].endswith('/overview')], .95))})

safe = {'date': RESULT['date'], 'passed': RESULT['passed'], 'durationMs': RESULT['durationMs'], 'summary': SUMMARY, 'phases': phase_stats, 'routes': routes, 'snapshots': [{k:s[k] for k in ('t','phase','active','queued')} for s in RESULT['snapshots']], 'remoteMetrics': RESULT['remoteMetrics'], 'before': BEFORE['phases'][0], 'firstFullErrors': BASELINE['firstFullErrors'], 'counts': counts}
(OUTPUT / 'summary.json').write_text(json.dumps(safe, ensure_ascii=False, indent=2))

shots = [
    ('stress-teacher-live.png', '教师总览', '真实浏览器连接压力测试课堂；学生身份全部为本次新建的合成账号。'),
    ('stress-monitor-desktop.png', '巡视窗口 · 桌面', '独立巡视窗口读取服务器状态，截图是在持续负载期间抓取。'),
    ('stress-monitor-mobile.png', '巡视窗口 · 手机宽度', '390 px 视口，验证信息在窄屏中的可读性。'),
    ('stress-student-live.png', '学生工作区', '学生页面连接同一压力测试账号，读取固定运行快照与编译结果。'),
    ('stress-interactive-eof.png', '交互输入与 EOF', '浏览器发送文本后真正关闭 stdin，并展示程序继续执行后的输出。'),
    ('stress-compile-error.png', '原始编译诊断', '语法错误由远端 GCC 产生，保留源码快照和完整诊断。'),
]
gallery = []
for filename, title, caption in shots:
    path = ROOT / 'output/playwright' / filename
    if not path.exists():
        continue
    caption += ' · 截图于 ' + datetime.fromtimestamp(path.stat().st_mtime, ZoneInfo('Asia/Shanghai')).strftime('%H:%M:%S CST')
    data = 'data:image/png;base64,' + base64.b64encode(path.read_bytes()).decode()
    gallery.append(f'<figure class="shot"><button class="image-button" type="button" data-image="true" data-caption="{html.escape(title)}" aria-label="放大：{html.escape(title)}"><img src="{data}" alt="{html.escape(title)}，真实浏览器截图" loading="lazy"></button><figcaption><strong>{html.escape(title)}</strong><span>{html.escape(caption)}</span></figcaption></figure>')

bursts = [p for p in PHASES if p['name'].startswith('burst-')]
soak = next(p for p in PHASES if p['name'].startswith('soak-'))
completed = sum(p.get('completed', 0) for p in PHASES)
before_admission = BEFORE['phases'][0]
admission = next(p for p in PHASES if p['name'].startswith('admission-'))
local_date = datetime.fromisoformat(RESULT['date'].replace('Z', '+00:00')).astimezone(ZoneInfo('Asia/Shanghai')).strftime('%Y.%m.%d %H:%M')

TEMPLATE = r'''<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><title>C++ Classroom 压力测试 · 数据与截图报告</title>
<style>
:root{--paper:#f5f2eb;--surface:#fffdf8;--ink:#222923;--muted:#72786e;--line:#d9ddd2;--accent:#b4472d;--green:#2c6755;--blue:#436d9c;--wash:#e6e9de;--shadow:0 22px 65px #18241e12;--mono:ui-monospace,SFMono-Regular,Consolas,monospace;color-scheme:light}
@media(prefers-color-scheme:dark){:root:not([data-theme=light]){--paper:#161c19;--surface:#1f2722;--ink:#e3e8de;--muted:#a1af9f;--line:#3c473e;--accent:#ef9876;--green:#9ccbbb;--blue:#a1bfeb;--wash:#29342c;--shadow:0 22px 65px #0003;color-scheme:dark}}
:root[data-theme=dark]{--paper:#161c19;--surface:#1f2722;--ink:#e3e8de;--muted:#a1af9f;--line:#3c473e;--accent:#ef9876;--green:#9ccbbb;--blue:#a1bfeb;--wash:#29342c;--shadow:0 22px 65px #0003;color-scheme:dark}
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:30px}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.8 -apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif}button,a{-webkit-tap-highlight-color:transparent}button{font:inherit;color:inherit;cursor:pointer}a{color:inherit;text-decoration-thickness:1px;text-underline-offset:5px}button:focus-visible,a:focus-visible{outline:3px solid var(--accent);outline-offset:4px}.wrap{max-width:1280px;padding:0 44px;margin:auto}header{border-bottom:1px solid var(--line)}.topline{display:flex;align-items:center;justify-content:space-between;padding:24px 0;gap:20px}.wordmark{font:600 13px var(--mono);letter-spacing:.12em}.top-actions{display:flex;gap:20px;align-items:center}.top-actions a{font-size:12px;text-decoration:none;color:var(--muted)}.theme{border:1px solid var(--line);background:transparent;border-radius:50%;width:38px;height:38px;font-size:18px}.hero{padding:74px 0 50px;display:grid;grid-template-columns:1fr 300px;gap:40px}.eyebrow,.section-no{font:12px var(--mono);letter-spacing:.14em;color:var(--accent)}h1,h2{font-family:"Songti SC","STSong","Noto Serif CJK SC",serif;font-weight:600;letter-spacing:-.035em}h1{font-size:clamp(36px,5.4vw,70px);line-height:1.18;margin:20px 0 24px}h1 span{display:block;color:var(--muted);font-size:.72em;margin-top:14px}.lead{font-size:17px;max-width:690px;color:var(--muted);margin:0}.verdict{align-self:end;border-left:2px solid var(--green);padding:4px 0 4px 24px}.verdict strong{display:block;font-size:21px;color:var(--green)}.verdict p{font-size:13px;color:var(--muted);margin:8px 0}.stamp{display:block;font:12px var(--mono);color:var(--muted);margin-top:20px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin-bottom:70px}.metric{padding:26px 20px 27px 0}.metric+.metric{border-left:1px solid var(--line);padding-left:26px}.metric label{font-size:12px;color:var(--muted)}.metric b{display:block;font:500 clamp(31px,4vw,48px)/1.25 var(--mono);letter-spacing:-.07em;margin:12px 0 7px}.metric small{font-size:12px;color:var(--muted)}section{margin-bottom:82px}.section-head{display:flex;justify-content:space-between;gap:30px;align-items:flex-end;margin-bottom:24px}.section-head h2{font-size:30px;margin:8px 0 0;line-height:1.3}.section-head p{max-width:490px;color:var(--muted);font-size:13px;margin:0}.boundary{display:grid;grid-template-columns:1fr 1.3fr;background:var(--surface);border:1px solid var(--line);padding:30px;gap:42px}.boundary h3{margin:0 0 12px;font-size:20px}.boundary p{font-size:14px;color:var(--muted);margin:0}.before-after{display:grid;grid-template-columns:1fr 1fr;gap:26px}.before-after small{display:block;font:11px var(--mono);color:var(--muted);letter-spacing:.1em}.before-after b{display:block;font:500 55px/1.2 var(--mono);letter-spacing:-.07em;margin:8px 0}.before-after .before b{color:var(--accent)}.before-after .after b{color:var(--green)}.before-after span{display:block;font-size:12px;color:var(--muted)}.chart-card{padding:28px;background:var(--surface);border:1px solid var(--line)}.chart-top{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:20px}.chart-title{font-weight:600}.filters{display:flex;gap:5px;flex-wrap:wrap}.filters button{border:1px solid var(--line);background:transparent;font-size:12px;padding:5px 10px;border-radius:2px}.filters button[aria-pressed=true]{background:var(--ink);color:var(--paper);border-color:var(--ink)}svg.chart{width:100%;height:auto;display:block;overflow:visible;font-family:var(--mono)}.grid-line{stroke:var(--line);stroke-dasharray:3 6}.axis-label{fill:var(--muted);font-size:11px}.legend{display:flex;gap:24px;flex-wrap:wrap;font-size:12px;color:var(--muted);margin-top:14px}.legend i{display:inline-block;width:14px;height:3px;vertical-align:middle;margin-right:7px;background:var(--accent)}.two-col{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:22px}.footnote{font-size:12px;color:var(--muted);margin:14px 0 0}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:13px;white-space:nowrap}th{text-align:left;font-weight:500;color:var(--muted);font-size:11px;padding:16px 14px 13px;border-bottom:1px solid var(--line)}td{padding:15px 14px;border-bottom:1px solid var(--line)}td.num,th.num{text-align:right;font-family:var(--mono)}tr:last-child td{border-bottom:0}.status{display:inline-flex;align-items:center;gap:6px;color:var(--green);font-size:12px}.status:before{content:"";width:5px;height:5px;border-radius:50%;background:currentColor}.soak{display:grid;grid-template-columns:1fr 1fr 1fr;gap:25px;margin-top:24px}.soak article{border-top:2px solid var(--green);padding-top:17px}.soak b{font:500 32px/1.4 var(--mono);letter-spacing:-.04em}.soak p{color:var(--muted);font-size:12px;margin:6px 0 0}.gallery{display:grid;grid-template-columns:1fr 1fr;gap:30px 24px}.shot{margin:0;min-width:0}.image-button{width:100%;padding:0;display:block;border:1px solid var(--line);background:var(--surface);overflow:hidden;box-shadow:var(--shadow)}.image-button img{display:block;width:100%;height:310px;object-fit:contain;object-position:top;background:#fff;transition:transform .25s}.image-button:hover img{transform:scale(1.015)}figcaption{padding-top:15px}figcaption strong{font-weight:600;font-size:14px;display:block}figcaption span{display:block;font-size:12px;color:var(--muted);margin-top:5px}.methodology{display:grid;grid-template-columns:1fr 1fr;gap:36px}.methodology h3{font-size:16px;margin:0 0 14px}.methodology ul{padding-left:18px;margin:0;color:var(--muted);font-size:13px}.methodology li{margin:9px 0}.callout{border-left:2px solid var(--accent);padding:12px 20px;color:var(--muted);background:var(--surface);font-size:13px;margin-top:28px}.downloads{display:flex;gap:12px;flex-wrap:wrap;margin-top:25px}.download{padding:9px 15px;border:1px solid var(--line);background:var(--surface);font-size:12px}.bottom{padding:26px 0;border-top:1px solid var(--line);display:flex;gap:20px;justify-content:space-between;font-size:11px;color:var(--muted)}dialog{border:1px solid var(--line);background:var(--surface);color:var(--ink);max-width:min(96vw,1550px);padding:20px}dialog::backdrop{background:#000b;backdrop-filter:blur(5px)}dialog img{display:block;max-width:100%;max-height:80vh;object-fit:contain}dialog .dialog-head{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:12px}dialog button{background:transparent;border:1px solid var(--line);padding:3px 12px}.phase-note{font-size:12px;color:var(--muted);min-height:22px}.state-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin-top:24px}.state-grid article{background:var(--surface);border:1px solid var(--line);padding:18px}.state-grid b{font:500 29px var(--mono);display:block;margin:6px 0}.state-grid span{font-size:12px;color:var(--muted)}
@media(max-width:780px){.wrap{padding:0 22px}.hero{padding-top:44px;grid-template-columns:1fr;gap:30px}.verdict{padding-left:18px}.metrics{grid-template-columns:1fr 1fr;margin-bottom:48px}.metric{padding:20px 0}.metric+.metric{padding-left:18px}.metric:nth-child(3){padding-left:0;border-left:0;border-top:1px solid var(--line)}.metric:nth-child(4){border-top:1px solid var(--line)}.section-head{display:block}.section-head p{margin-top:12px}.boundary{grid-template-columns:1fr;padding:22px;gap:28px}.two-col,.gallery,.methodology{grid-template-columns:1fr}.chart-card{padding:18px 14px}.chart-top{align-items:flex-start;flex-direction:column}.section-head h2{font-size:26px}.soak{gap:12px}.soak b{font-size:24px}.soak p{font-size:11px}.top-actions a{display:none}section{margin-bottom:54px}.image-button img{height:240px}.state-grid{grid-template-columns:1fr 1fr}.bottom{flex-direction:column;gap:4px}.before-after b{font-size:47px}td,th{padding-left:10px;padding-right:10px}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}
</style></head><body>
<header><div class="wrap topline"><span class="wordmark">C++ CLASSROOM / FIELD NOTES</span><div class="top-actions"><a href="#results">负载结果</a><a href="#screenshots">真实截图</a><a href="#methods">方法与边界</a><button class="theme" type="button" id="theme" aria-label="切换深浅色">◐</button></div></div></header>
<main class="wrap"><div class="hero"><div><div class="eyebrow">PERFORMANCE REVIEW · 2026.10.25</div><h1>C++ 教室压力测试<span>从并发边界，到持续负载。</span></h1><p class="lead">120 个独立合成账号，分档集中编译、持续编辑、异常程序与交互 EOF。这里展示本次实测数据，以及连接同一服务的浏览器截图。</p></div><aside class="verdict"><strong>__VERDICT__</strong><p>__COMPLETED__ 次运行逐一核对预期结果。409 为预期的限流拒绝；超时与资源超限按测试目标判定，不计作平台失败。</p><span class="stamp">__DATE__ CST<br>原生 Linux · AIM-Radar</span></aside></div>
<div class="metrics"><div class="metric"><label>独立合成账号</label><b>120</b><small>跨 3 个课堂，单课堂最多 50 人</small></div><div class="metric"><label>完成并校验的运行</label><b>__COMPLETED__</b><small>包含预期错误与交互任务</small></div><div class="metric"><label>测量阶段 HTTP 请求</label><b>__REQUESTS__</b><small>意外错误 __ERRORS__ · 预期限流单独记录</small></div><div class="metric"><label>100 人档运行 P95</label><b>__P95__<small> s</small></b><small>包括保存、入队、编译、执行和轮询</small></div></div>
<section><div class="section-head"><div><span class="section-no">01 / THE BOUNDARY</span><h2>先发现问题，再证明修复。</h2></div><p>120 人同时提交时，旧入队逻辑先计数、后写入，两个操作之间存在并发窗口。本次已将接纳检查与入队纳入共享事务锁。</p></div><div class="boundary"><div><h3>活动任务上限：100</h3><p>修复前保留了失败样本；修复后相同边界测试接纳 100、拒绝 20，另外 10 次重复运行请求也被拒绝。4 个执行槽与 100 个活动任务是两个不同限制。</p></div><div class="before-after"><div class="before"><small>BEFORE / ACCEPTED</small><b>__BEFORE__</b><span>超出约定上限，边界测试失败</span></div><div class="after"><small>AFTER / ACCEPTED</small><b>__AFTER__</b><span>120 次提交 → 100 接纳 / 20 拒绝</span></div></div></div></section>
<section><div class="section-head"><div><span class="section-no">01B / THE TRANSPORT</span><h2>无限输出，也不能拖垮别人的握手。</h2></div><p>第一轮异常混合负载中，一个正常程序出现 WebSocket 握手超时，HTTP 统计本身仍是零意外错误。两个指标不能混为一谈。</p></div><div class="boundary"><div><h3>把限制前移到 Linux 节点</h3><p>此前网关收到超量输出后才取消，输出流可能已经挤占共享 SSH 链路。本次增加执行节点的 streamOut.max 字节上限，在节点上截断、取消并返回明确终态；网关同时保留合计字节限制，并将 SSH 链路上的 WebSocket 握手超时由 5 秒调整为 15 秒。</p></div><div><p>修复后重新执行完整负载矩阵，并单独核对 50 个混合异常任务与 20 个交互 EOF 任务。新增 Go 测试验证有界输出先于输出超限终态发送。</p><p style="margin-top:14px">引擎版本：<span style="font-family:var(--mono)">v1.13.3-classroom-eof.2</span></p></div></div></section><section id="results"><div class="section-head"><div><span class="section-no">02 / BURST LOAD</span><h2>不同并发，测量完整运行耗时。</h2></div><p>每档两轮，GCC 13.3 / C++17，单文件整数平方程序。每份输入不同，逐一核对输出，避免只测“请求成功”。</p></div><div class="chart-card"><div class="chart-top"><span class="chart-title">集中运行完成耗时</span><div class="filters" id="burstFilters"><button aria-pressed="true" data-stat="totalP95Ms">P95</button><button aria-pressed="false" data-stat="totalP50Ms">P50</button><button aria-pressed="false" data-stat="totalP99Ms">P99</button></div></div><svg class="chart" id="burstChart" viewBox="0 0 1080 280" role="img" aria-label="不同并发人数的运行总耗时图"></svg><p class="footnote">耗时为负载发起到负载工具观察终态；其中含至多约 300 ms 的结果轮询间隔，不等同于程序 CPU 时间。本轮没有独立量化排队、编译和网络各自占比，不据此判定唯一瓶颈。</p></div><div class="table-wrap"><table><thead><tr><th>并发人数</th><th class="num">校验完成</th><th class="num">P50 / 秒</th><th class="num">P95 / 秒</th><th class="num">P99 / 秒</th><th class="num">意外 HTTP 错误</th></tr></thead><tbody id="burstRows"></tbody></table></div></section>
<section><div class="section-head"><div><span class="section-no">03 / SUSTAINED LOAD</span><h2>50 人继续写，程序继续跑。</h2></div><p>持续 120 秒独立编辑循环，每人约 800 ms 一次保存；运行循环并行进行，另有 5 秒心跳与教师每秒巡视读取。最后等待队列排空。</p></div><div class="chart-card"><div class="chart-top"><span class="chart-title">实际队列与执行槽</span><div class="filters" id="phaseFilters"><button aria-pressed="true" data-phase="all">全部阶段</button><button aria-pressed="false" data-phase="burst-100">100 人集中</button><button aria-pressed="false" data-phase="soak-50-120s">持续编辑</button><button aria-pressed="false" data-phase="mixed-50">异常混合</button></div></div><svg class="chart" id="queueChart" viewBox="0 0 1080 270" role="img" aria-label="队列和活动执行任务时间序列"></svg><div class="legend"><span><i></i>排队任务</span><span><i style="background:var(--green)"></i>实际执行任务</span></div><p class="phase-note" id="phaseNote"></p></div><div class="soak"><article><b>__SAVES__</b><p>持续编辑期间成功保存次数</p></article><article><b>__SAVE_P95__ ms</b><p>持续编辑保存请求 P95</p></article><article><b>__OVERVIEW_P95__ ms</b><p>整个测量阶段教师总览读取 P95</p></article></div><div class="two-col"><div class="chart-card"><div class="chart-title">Linux 主机 CPU / %</div><svg class="chart" id="cpuChart" viewBox="0 0 500 220" role="img" aria-label="Linux 主机 CPU 使用率"></svg><p class="footnote">16 个逻辑 CPU 的整机平均值，包含主机其他进程。</p></div><div class="chart-card"><div class="chart-title">Linux 主机已用内存 / GiB</div><svg class="chart" id="memoryChart" viewBox="0 0 500 220" role="img" aria-label="Linux 主机内存使用量"></svg><p class="footnote">按 MemTotal − MemAvailable 计算；非单个程序或单个进程 RSS。</p></div></div></section>
<section><div class="section-head"><div><span class="section-no">04 / EXPECTED FAILURES</span><h2>故意出错，也应有明确终态。</h2></div><p>50 个混合任务同时入队：30 个正常程序、5 个死循环、5 个内存压力、5 个无限输出、5 个语法错误；另外验证 20 个交互输入与 EOF 任务。</p></div><div class="state-grid" id="stateGrid"></div><div class="callout">“超时”“资源超限”“编译失败”是这些样本的预期结果。报告把这些终态与平台错误、HTTP 意外错误分开统计，避免把受控终止误报为系统故障。</div></section>
<section id="screenshots"><div class="section-head"><div><span class="section-no">05 / BROWSER EVIDENCE</span><h2>数据之外，保留现场。</h2></div><p>以下是实际页面截图，不是设计稿。所有图片内嵌在这一个 HTML 中，点击可放大；无需再下载本地附件。</p></div><div class="gallery">__GALLERY__</div></section>
<section><div class="section-head"><div><span class="section-no">06 / REQUEST PROFILE</span><h2>关键 API 的响应分布。</h2></div><p>只统计测量阶段，排除账号准备和清理。预期的 409 仍记录延迟，但不算意外错误。</p></div><div class="chart-card table-wrap"><table><thead><tr><th>请求</th><th class="num">次数</th><th class="num">P50 / ms</th><th class="num">P95 / ms</th><th class="num">P99 / ms</th><th class="num">意外错误</th></tr></thead><tbody id="routeRows"></tbody></table></div></section>
<section id="methods"><div class="section-head"><div><span class="section-no">07 / METHOD & LIMITS</span><h2>这些数字能证明什么。</h2></div></div><div class="methodology"><div><h3>本次环境与方法</h3><ul><li>业务 API 与 worker：开发机上的编译后原生 Node.js 常驻进程。前端为 Vite 开发预览。</li><li>执行节点：AIM-Radar，原生 Linux、16 逻辑 CPU、约 31 GiB 内存，GCC 13.3 / C++17。</li><li>执行通过认证 SSH 隧道接入；全局最多 4 个执行任务，最多 100 个活动任务。</li><li>120 个合成账号跨 3 个课堂；测试记录与真实课堂隔离，不重置数据库。</li><li>HTTP 使用独立 Cookie 会话；集中运行档位分别为 10、25、50、100，均为两轮。</li><li>队列从 PostgreSQL 每 200 ms 采样，主机 CPU 与内存每秒采样；截图来自独立的真实浏览器会话。</li></ul></div><div><h3>解释与边界</h3><ul><li>这不是 120 台浏览器的完整端到端并发，界面由少量真实浏览器单独取证。</li><li>本次测试持续数分钟，不等同于长时间稳定性测试，也不能直接外推公网、多班长期授课表现。</li><li>CPU 和内存曲线为整机值，包含节点上其他已有服务；CPU 峰值不是评测服务独占 CPU。</li><li>网络、编译、排队和轮询都进入运行总耗时。API P95 与运行 P95 是不同指标。</li><li>系统 VPN 直连此前未成功；本次测量使用实际可用的 SSH 隧道链路。</li><li>凭据、令牌、内网地址、真实学生信息均未包含在公开报告和截图中。</li></ul></div></div><div class="downloads"><button class="download" id="downloadData">下载脱敏汇总 JSON</button><button class="download" onclick="window.print()">打印 / 保存为 PDF</button><a class="download" href="#screenshots">回到截图</a></div></section>
<footer class="bottom"><span>C++ Classroom · native execution performance review</span><span>__DATE__ CST · 一份自包含、可转发的实测报告</span></footer></main>
<dialog id="lightbox"><div class="dialog-head"><strong id="imageCaption"></strong><button type="button" id="closeImage" aria-label="关闭大图">关闭 ×</button></div><img id="largeImage" alt="放大的真实浏览器截图"></dialog>
<script id="report-data" type="application/json">__DATA__</script>
<script>
const D=JSON.parse(document.getElementById('report-data').textContent);const $=id=>document.getElementById(id);const fmt=n=>Number(n).toLocaleString('en-US');
const bursts=D.phases.filter(p=>p.name.startsWith('burst-'));const colors={accent:'var(--accent)',green:'var(--green)',blue:'var(--blue)'};
function escapeHTML(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function burst(stat='totalP95Ms') {const max=Math.max(...bursts.map(p=>p[stat]))/1000*1.16;const width=Math.max(300,Math.round($('burstChart').getBoundingClientRect().width));$('burstChart').setAttribute('viewBox',`0 0 ${width} 280`);const left=56,right=30,top=30,bottom=240,inner=width-left-right;let s='';for(let i=0;i<=4;i++){const v=max*i/4,y=bottom-(bottom-top)*i/4;s+=`<line x1="${left}" y1="${y}" x2="${width-right}" y2="${y}" class="grid-line"/><text x="${left-12}" y="${y+4}" text-anchor="end" class="axis-label">${v.toFixed(1)}s</text>`}bursts.forEach((p,i)=>{const val=p[stat]/1000,x=left+inner*(i+.5)/bursts.length,bw=Math.min(140,inner/bursts.length*.6),height=(val/max)*(bottom-top);s+=`<rect x="${x-bw/2}" y="${bottom-height}" width="${bw}" height="${height}" fill="${i===3?'var(--accent)':'var(--green)'}" opacity="${i===3?1:.75}"/><text x="${x}" y="${bottom-height-12}" text-anchor="middle" fill="var(--ink)" font-size="15">${val.toFixed(2)} s</text><text x="${x}" y="${bottom+26}" text-anchor="middle" class="axis-label">${p.users} 人</text>`});$('burstChart').innerHTML=s}
function line(svgId,data,series,{width=1080,height=270,yMax=null,unit='',phaseName='all'}={}){const svg=$(svgId);width=Math.max(300,Math.round(svg.getBoundingClientRect().width));svg.setAttribute('viewBox',`0 0 ${width} ${height}`);if(!data.length){svg.innerHTML='<text x="30" y="70" fill="var(--muted)">本轮未获取到主机遥测</text>';return}const L=50,R=18,T=22,B=height-38;const first=data[0].t,last=data[data.length-1].t;let max=yMax??Math.max(...data.flatMap(d=>series.map(s=>Number(s.get(d))||0)))*1.1;max=Math.max(max,1);let html='';for(let i=0;i<=4;i++){const y=B-(B-T)*i/4;html+=`<line x1="${L}" y1="${y}" x2="${width-R}" y2="${y}" class="grid-line"/><text x="${L-9}" y="${y+4}" text-anchor="end" class="axis-label">${(max*i/4).toFixed(unit==='GiB'?1:0)}${unit}</text>`}for(let i=0;i<=4;i++){const sec=(last-first)*i/4000;html+=`<text x="${L+(width-L-R)*i/4}" y="${B+24}" text-anchor="middle" class="axis-label">${sec.toFixed(0)}s</text>`}for(const s of series){const points=data.map(d=>`${L+(d.t-first)/Math.max(1,last-first)*(width-L-R)},${B-s.get(d)/max*(B-T)}`).join(' ');html+=`<polyline points="${points}" fill="none" stroke="${s.color}" stroke-width="2.4" vector-effect="non-scaling-stroke" stroke-linejoin="round"/>`;}svg.innerHTML=html}
function queue(phase='all'){const data=phase==='all'?D.snapshots:D.snapshots.filter(s=>s.phase===phase);line('queueChart',data,[{get:d=>d.queued,color:colors.accent},{get:d=>d.active,color:colors.green}],{yMax:100});const peak=data.length?Math.max(...data.map(d=>d.active)):0;const queued=data.length?Math.max(...data.map(d=>d.queued)):0;$('phaseNote').textContent=`${data.length} 个数据库采样点 · 峰值实际执行 ${peak} · 峰值排队 ${queued}。活动任务上限包括排队与执行。`}
$('burstRows').innerHTML=bursts.map(p=>`<tr><td>${p.users} 人 × 2 轮</td><td class="num">${p.completed}</td><td class="num">${(p.totalP50Ms/1000).toFixed(2)}</td><td class="num">${(p.totalP95Ms/1000).toFixed(2)}</td><td class="num">${(p.totalP99Ms/1000).toFixed(2)}</td><td class="num">${p.unexpectedErrors}</td></tr>`).join('');
$('routeRows').innerHTML=D.routes.map(r=>`<tr><td><span style="font-family:var(--mono);font-size:11px">${escapeHTML(r.method+' '+r.route)}</span></td><td class="num">${fmt(r.count)}</td><td class="num">${r.p50}</td><td class="num">${r.p95}</td><td class="num">${r.p99}</td><td class="num">${r.errors}</td></tr>`).join('');
$('stateGrid').innerHTML=[['正常输出',D.counts['运行完成']??0],['超时受控',D.counts['超时']??0],['资源超限',D.counts['资源超限']??0],['语法错误',D.counts['编译失败']??0]].map(([name,n])=>`<article><span>${name}</span><b>${n}</b><span>混合负载样本 / 符合预期</span></article>`).join('');
$('burstFilters').addEventListener('click',e=>{const b=e.target.closest('[data-stat]');if(!b)return;for(const s of $('burstFilters').querySelectorAll('button'))s.setAttribute('aria-pressed',String(s===b));burst(b.dataset.stat)});
$('phaseFilters').addEventListener('click',e=>{const b=e.target.closest('[data-phase]');if(!b)return;for(const s of $('phaseFilters').querySelectorAll('button'))s.setAttribute('aria-pressed',String(s===b));queue(b.dataset.phase)});
$('theme').addEventListener('click',()=>{const dark=document.documentElement.dataset.theme?document.documentElement.dataset.theme==='dark':matchMedia('(prefers-color-scheme:dark)').matches;document.documentElement.dataset.theme=dark?'light':'dark'});
for(const b of document.querySelectorAll('[data-image]'))b.addEventListener('click',()=>{$('largeImage').src=b.querySelector('img').src;$('imageCaption').textContent=b.dataset.caption;$('lightbox').showModal()});$('closeImage').onclick=()=>$('lightbox').close();$('lightbox').addEventListener('click',e=>{if(e.target===$('lightbox'))$('lightbox').close()});
$('downloadData').onclick=()=>{const blob=new Blob([JSON.stringify(D,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='cpp-classroom-stress-summary.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
burst();queue();line('cpuChart',D.remoteMetrics,[{get:d=>d.cpu,color:colors.blue}],{width:500,height:220,yMax:100,unit:'%'});line('memoryChart',D.remoteMetrics,[{get:d=>d.memoryUsedMiB/1024,color:colors.green}],{width:500,height:220,unit:'GiB'});
</script></body></html>'''

values = {
    '__VERDICT__': '本轮负载测试通过' if RESULT['passed'] else '本轮存在失败项，见明细',
    '__COMPLETED__': f'{completed:,}', '__DATE__': local_date,
    '__REQUESTS__': f"{SUMMARY['requests']:,}", '__ERRORS__': str(SUMMARY['unexpectedErrors']),
    '__P95__': f"{next(p for p in bursts if p['users']==100)['totalP95Ms']/1000:.2f}",
    '__BEFORE__': str(before_admission['accepted']), '__AFTER__': str(admission['accepted']),
    '__SAVES__': f"{soak['saveCycles']:,}", '__SAVE_P95__': str(soak['saveP95Ms']),
    '__OVERVIEW_P95__': str(SUMMARY['teacherOverviewP95Ms']),
    '__GALLERY__': ''.join(gallery), '__DATA__': json.dumps(safe, ensure_ascii=False, separators=(',', ':')).replace('</', '<\\/'),
}
result = TEMPLATE
for key, value in values.items():
    result = result.replace(key, value)
assert '__DATA__' not in result
(OUTPUT / 'index.html').write_text(result)
print(json.dumps({'file': str(OUTPUT/'index.html'), 'bytes': len(result.encode()), 'screenshots': len(gallery), 'completed': completed}, ensure_ascii=False))
